from pathlib import Path
import hashlib,json,difflib,sys
site=Path('relief-studio');base=Path(sys.argv[1]).read_text();p=site/'source/public/diagnostics.js';s=p.read_text();dst=site/'upgrade19.json';d=json.loads(dst.read_text());c=d['changes']['public/diagnostics.js'];sha=lambda v:hashlib.sha256(v.encode()).hexdigest();assert sha(base)==c['base'] and sha(s)==c['result']
s=s.replace(" if(d.objectId)facts.push('Objekt '+d.objectId);", " if(d.objectId)facts.push('Objekt '+d.objectId);\n if(code==='IMPORT_HEIGHT'&&typeof d.height==='number')facts.push('Gelieferte Höhe: '+d.height+' m');\n if(code==='IMPORT_TERRAIN_GRID')facts.push('Gelesen: '+(d.cols??'?')+' Spalten × '+(d.rows??'?')+' Zeilen, '+(d.actualValues??'?')+' Höhenwerte');")
s=s.replace('  const info=explainFailure(input,context.stage',"  // On failed import the current editor state belongs to the previous project.\n  if(context.stage==='Import')state={...state,data:null,settings:null,bounds:null};\n  const info=explainFailure(input,context.stage");assert sha(s)=='49751599dff52d32091466d0ddf1d21d9a5d432bf020e2d7a611370c73b66717';p.write_text(s);a,b=base.split('\n'),s.split('\n');c.update(result=sha(s),edits=[[i,j-i,b[k:l]] for tag,i,j,k,l in difflib.SequenceMatcher(None,a,b,autojunk=False).get_opcodes() if tag!='equal']);new=json.dumps(d,ensure_ascii=False,separators=(',',':'))+'\n';assert sha(new)=='3c6542ca1164ecfb788e43868426c90db0f7e7ed6df66d8aeb503a1a2f7d41bc';dst.write_text(new)
f=site/'source/tests/diagnose19.test.mjs';f.write_text(f.read_text()+'''test('Failed import does not attribute the previous project to the bad file and shows the actual invalid value',()=>{const d=RS.createDiagnostics();d.setProvider(()=>({settings:{title:'Altes Projekt'},bounds:[1,2,3,4],data:{old:true}}));d.begin('Import');const e=Object.assign(Error('Ungültige Gebäudehöhe.'),{code:'IMPORT_HEIGHT',diagnostics:{objectId:'way/123',height:-2}});const r=d.capture(e,{stage:'Import'});assert.match(r.displayMessage,/Gelieferte Höhe: -2 m/);assert(r.displayMessage.includes('way/123'));assert(!r.displayMessage.includes('Altes Projekt'));const j=d.report();assert.equal(j.settings,null);assert.equal(j.data,null);assert.equal(j.diagnostics.state.bounds,null);const grid=d.capture(Object.assign(Error('Raster'),{code:'IMPORT_TERRAIN_GRID',diagnostics:{cols:2.5,rows:2,actualValues:5}}),{stage:'Import'});assert.match(grid.displayMessage,/2.5 Spalten × 2 Zeilen, 5 Höhenwerte/);});\n''')
f=site/'RELEASE-NOTES-19.md';f.write_text(f.read_text()+'\nUngültige Importdateien übernehmen weder Ortsnamen noch Kartendaten des vorherigen Projekts. Zahlenfehler zeigen den tatsächlich gelesenen Wert; beispielsweise −2 m Gebäudehöhe oder 2,5 Rasterspalten.\n')
f=site/'reports/v19/acceptance.json';v=json.loads(f.read_text());v['unitAndRegressionSuite']['passed']=212;v['negativeBrowserCases']['passed'] += [['Import','IMPORT_HEIGHT'],['Import','IMPORT_TERRAIN_GRID'],['Geländedaten','TERRAIN / TILE_DECODE']];v['negativeBrowserCases']['followup']='Broken input does not inherit a previous city or project in its error snapshot. Height/raster readouts show actual input values; an unreadable PNG reports the affected tile.';v['geometryAudit']={'cases':7,'closedConnectedComponentsPerCase':1,'openOrMispairedEdges':0,'degenerateTriangles':0,'note':'Rebuilt independently from the seven saved or recorded inputs; not an audit of the four separately downloaded live maps.'};f.write_text(json.dumps(v,ensure_ascii=False,indent=2)+'\n')
